"""Strict, bounded decoding of recorded KTEST v3 objects.

Transport errors are local to a witness.  Layout/value validation is deliberately
separate from predicates, so a rejected input cannot hide a corrupt result.
"""
import base64
import binascii
import re
import struct


class InvalidTest(ValueError):
    """A malformed transport, inventory, or symbolic value."""


_NAME = re.compile(rb"x(?:0|[1-9][0-9]*)\Z")
_U32 = struct.Struct(">I")


def decode(payload, expected=None):
    """Return name -> bytes, optionally enforcing a name -> width inventory."""
    try:
        encoded = payload.encode("ascii")
        data = base64.b64decode(encoded, validate=True)
        if base64.b64encode(data) != encoded:
            raise InvalidTest("noncanonical base64")
    except (ValueError, UnicodeError, binascii.Error) as exc:
        raise InvalidTest("base64") from exc

    end = len(data)
    position = 5
    if data[:5] != b"KTEST":
        raise InvalidTest("magic")

    def u32():
        nonlocal position
        if position + 4 > end:
            raise InvalidTest("truncated integer")
        value = _U32.unpack_from(data, position)[0]
        position += 4
        return value

    def blob(limit=None):
        nonlocal position
        length = u32()
        if (limit is not None and length > limit) or length > end - position:
            raise InvalidTest("blob length")
        value = data[position:position + length]
        position += length
        return value

    if u32() != 3:
        raise InvalidTest("version")
    argc = u32()
    if argc > 64:
        raise InvalidTest("argument count")
    for _ in range(argc):
        blob(256)
    u32()  # symbolic argv count and length are opaque bookkeeping
    u32()
    count = u32()
    if count > (end - position) // 8:
        raise InvalidTest("object count")
    if expected is not None and count != len(expected):
        raise InvalidTest("inventory size")
    objects = {}
    for _ in range(count):
        name = blob()
        if _NAME.fullmatch(name) is None:
            raise InvalidTest("object name")
        name = name.decode("ascii")
        if name in objects or (expected is not None and name not in expected):
            raise InvalidTest("unknown or duplicate object")
        value = blob()
        if expected is not None and len(value) != expected[name]:
            raise InvalidTest("object width")
        objects[name] = value
    if position != end:
        raise InvalidTest("trailing bytes")
    return objects
