"""Dependency DAGs, with deterministic, root-scoped compilation."""
from collections import defaultdict
import heapq


class DependencyGraph:
    def __init__(self):
        self.graph = defaultdict(set)          # prerequisite -> dependents
        self.dependencies = defaultdict(set)   # dependent -> prerequisites
        self.filter_functions = []
        self.model_to_node = {}
        self.node_to_model = {}
        self.nodes = 0
        self.oracle = None

    def add_node(self, model):
        if model not in self.model_to_node:
            self.model_to_node[model] = self.nodes
            self.node_to_model[self.nodes] = model
            self.nodes += 1

    def add_edge(self, prerequisite, dependent):
        self.add_node(prerequisite)
        self.add_node(dependent)
        a, b = self.model_to_node[prerequisite], self.model_to_node[dependent]
        self.graph[a].add(b)
        self.dependencies[b].add(a)

    Edge = add_edge

    def CallEdge(self, model, dependency_models):
        for dependency in dependency_models:
            self.add_edge(dependency, model)

    def Pipe(self, target, filter_model):
        self.filter_functions.append(filter_model)
        self.add_edge(filter_model, target)

    Node = add_node

    def _order(self, included):
        degree = {node: len(self.dependencies[node] & included) for node in included}
        def key(node):
            model = self.node_to_model[node]
            return model if isinstance(model, str) else model.name
        ready = [(key(node), node) for node, n in degree.items() if n == 0]
        heapq.heapify(ready)
        result = []
        while ready:
            _, node = heapq.heappop(ready)
            result.append(node)
            for dependent in self.graph[node]:
                if dependent in degree:
                    degree[dependent] -= 1
                    if degree[dependent] == 0:
                        heapq.heappush(ready, (key(dependent), dependent))
        if len(result) != len(included):
            raise ValueError("cyclic module dependencies")
        return result

    def topologicalSort(self):
        return self._order(set(range(self.nodes)))

    def compile_order(self, root):
        # Iterative traversal: module depth can be much greater than type depth.
        pending = [self.model_to_node[root]]
        included = set()
        while pending:
            node = pending.pop()
            if node not in included:
                included.add(node)
                pending.extend(self.dependencies[node])
        return [self.node_to_model[node] for node in self._order(included)]
