"""Corpus identity and witness assembly (model results are not identity)."""
import json


def make_hashable(obj):
    """A reversible, type-tagged key; in particular [] != {} and False != 0."""
    if isinstance(obj, dict):
        return ("object", tuple(sorted((key, make_hashable(value)) for key, value in obj.items())))
    if isinstance(obj, (list, tuple)):
        return ("array", tuple(make_hashable(value) for value in obj))
    if isinstance(obj, bool):
        return ("bool", obj)
    if isinstance(obj, int):
        return ("int", obj)
    if isinstance(obj, str):
        return ("string", obj)
    if obj is None:
        return ("null",)
    raise TypeError("not a campaign value")


def recreate_structure(key):
    tag = key[0]
    if tag == "object":
        return {name: recreate_structure(value) for name, value in key[1]}
    if tag == "array":
        return [recreate_structure(value) for value in key[1]]
    return None if tag == "null" else key[1]


class Corpus:
    def __init__(self):
        self.entries = []
        self.indices = {}

    def add(self, entry, inputs, cost, commands, witness, result):
        # Canonical JSON is a compact type-preserving key, including for empty
        # aggregates. It also avoids retaining a second large tree of tuples.
        key = (entry, json.dumps(inputs, sort_keys=True, ensure_ascii=True,
                                 separators=(",", ":")))
        index = self.indices.get(key)
        if index is None:
            index = len(self.entries)
            self.indices[key] = index
            self.entries.append({"entry": entry, "inputs": inputs, "cost": cost,
                                 "commands": commands, "witnesses": [witness]})
            status = "READY"
        else:
            self.entries[index]["witnesses"].append(witness)
            status = "DUPLICATE"
        return {"status": status, "case": index, "model_result": result}
