    def prepare(self, target, evaluate_guard):
        """Return (cost, commands), or None.

        Reverse Dijkstra minimizes (cost,hops). Greedy reconstruction along
        optimal edges then minimizes the entire command sequence, without
        copying O(path length) tuples at every relaxation. Positive edge costs
        ensure reconstruction strictly descends the distances, even in cycles.
        """
        target = self.states[target]
        if target == self.initial:
            return 0, []
        enabled_cache = {-1: True}

        def enabled(guard):
            if guard not in enabled_cache:
                enabled_cache[guard] = bool(evaluate_guard(guard))
