        distances = [None] * len(self.states)
        distances[target] = (0, 0)
        queue = [(0, 0, target)]
        while queue:
            cost, hops, state = heapq.heappop(queue)
            if distances[state] != (cost, hops):
                continue
            if state == self.initial:
                break
            for source, _, _, weight, guard in self.reverse[state]:
                if not enabled(guard):
                    continue
                candidate = (cost + weight, hops + 1)
                if distances[source] is None or candidate < distances[source]:
                    distances[source] = candidate
                    heapq.heappush(queue, (*candidate, source))
        else:
            return None

        total = distances[self.initial][0]
        commands = []
        state = self.initial
        while state != target:
            cost, hops = distances[state]
            for _, destination, command, weight, guard in self.forward[state]:
                distance = distances[destination]
                if (distance is not None and distance[0] + weight == cost
                        and distance[1] + 1 == hops and enabled(guard)):
                    commands.append(command)
                    state = destination
                    break
            else:
                raise AssertionError("shortest-path reconstruction")
        return total, commands


